#!/usr/bin/env ruby

FILE = 'chapters/med_terms_s.tex'

SPECIAL = {
  'Schistosomiasis' => 'A parasitic disease caused by Schistosoma blood flukes acquired through freshwater exposure, potentially causing intestinal or urinary inflammation, bleeding, liver disease, or chronic organ damage.',
  'Scrofula' => 'Tuberculous infection of cervical lymph nodes, producing chronic neck swellings that may suppurate or form draining sinuses; nontuberculous mycobacteria can cause a similar presentation.',
  'Scurvy' => 'Vitamin C deficiency causing impaired collagen formation, with bleeding gums, easy bruising, petechiae, poor wound healing, anemia, bone pain, and fatigue.',
  'Spasticity' => 'Velocity-dependent increase in muscle tone caused by an upper motor-neuron lesion, producing stiffness, spasms, abnormal reflexes, and restricted movement.',
  'Strabismus' => 'Misalignment of the eyes so they do not point at the same target, causing double vision, abnormal head posture, or suppression and amblyopia in children.',
  'Stridor' => 'A harsh, high-pitched breathing sound caused by turbulent airflow through a narrowed upper airway; sudden or severe stridor can signal an airway emergency.',
  'Strongyloidiasis' => 'Intestinal infection by Strongyloides stercoralis acquired through skin contact with contaminated soil; it can persist for decades and cause fatal hyperinfection in immunosuppressed people.',
  'Sunburn' => 'Acute ultraviolet-induced injury to skin causing redness, warmth, pain, and sometimes blistering; severe burns can produce dehydration, infection, and systemic illness.',
  'Sweating' => 'Production of sweat by eccrine and apocrine glands for heat regulation and other responses; excessive, absent, or asymmetric sweating can indicate medication, autonomic, endocrine, or neurologic disease.',
